18	// InstallHooks installs Codex hooks in .codex/hooks.json.
19	func (c *CodexAgent) InstallHooks(ctx context.Context, force bool) (int, error) {
20		repoRoot, err := paths.WorktreeRoot(ctx)
21		if err != nil {
22			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
23			if err != nil {
24				return 0, fmt.Errorf("failed to get current directory: %w", err)
25			}
26		}
27	
28		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
29	
30		// Read existing hooks.json if present
31		var rawHooks map[string]json.RawMessage
32		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
33		if readErr == nil {
34			var hooksFile map[string]json.RawMessage
35			if err := json.Unmarshal(existingData, &hooksFile); err != nil {
36				return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
37			}
38			if hooksRaw, ok := hooksFile["hooks"]; ok {
39				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
40					return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
41				}
42			}
43		}
44	
45		if rawHooks == nil {
46			rawHooks = make(map[string]json.RawMessage)
47		}
48	
49		// Parse event types we manage
50		var sessionStart, userPromptSubmit, stop, postToolUse []MatcherGroup
51		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
52			return 0, err
53		}
54		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
55			return 0, err
56		}
57		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
58			return 0, err
59		}
60		if err := parseHookType(rawHooks, "PostToolUse", &postToolUse); err != nil {
61			return 0, err
62		}
63	
64		if force {
65			sessionStart = removeEntireHooks(sessionStart)
66			userPromptSubmit = removeEntireHooks(userPromptSubmit)
67			stop = removeEntireHooks(stop)
68			postToolUse = removeEntireHooks(postToolUse)
69		}
70	
71		// Build hook commands
72		const cmdPrefix = "entire hooks codex "
73		useWindowsProductionHooks := agent.UseWindowsProductionHooks(ctx)
74		sessionStartCmd := agent.WrapProductionJSONWarningHookCommandForOS(cmdPrefix+"session-start", agent.WarningFormatSingleLine, useWindowsProductionHooks)
75		userPromptSubmitCmd := agent.WrapProductionSilentHookCommandForOS(cmdPrefix+"user-prompt-submit", useWindowsProductionHooks)
76		stopCmd := agent.WrapProductionSilentHookCommandForOS(cmdPrefix+"stop", useWindowsProductionHooks)
77		postToolUseCmd := agent.WrapProductionSilentHookCommandForOS(cmdPrefix+"post-tool-use", useWindowsProductionHooks)
78	
79		count := 0
80	
81		if updated, changed := syncHookCommand(sessionStart, sessionStartCmd); changed {
82			sessionStart = updated
83			count++
84		}
85		if updated, changed := syncHookCommand(userPromptSubmit, userPromptSubmitCmd); changed {
86			userPromptSubmit = updated
87			count++
88		}
89		if updated, changed := syncHookCommand(stop, stopCmd); changed {
90			stop = updated
91			count++
92		}
93		if updated, changed := syncHookCommand(postToolUse, postToolUseCmd); changed {
94			postToolUse = updated
95			count++
96		}
97	
98		if count == 0 {
99			return 0, nil
100		}
101	
102		// Marshal modified types back
103		marshalHookType(rawHooks, "SessionStart", sessionStart)
104		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
105		marshalHookType(rawHooks, "Stop", stop)
106		marshalHookType(rawHooks, "PostToolUse", postToolUse)
107	
108		// Preserve existing top-level keys (e.g., $schema) by reusing the parsed file
109		topLevel := make(map[string]json.RawMessage)
110		if readErr == nil {
111			// Re-parse the original file to preserve all top-level keys
112			_ = json.Unmarshal(existingData, &topLevel) //nolint:errcheck // best-effort preservation
113		}
114		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
115		if err != nil {
116			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
117		}
118		topLevel["hooks"] = hooksJSON
119	
120		// Write to file
121		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
122			return 0, fmt.Errorf("failed to create .codex directory: %w", err)
123		}
124	
125		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
126		if err != nil {
127			return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
128		}
129	
130		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
131			return 0, fmt.Errorf("failed to write hooks.json: %w", err)
132		}
133	
134		// No .codex/config.toml is written: hooks are enabled by default in
135		// Codex (since 0.124.0), and a TOML file inside Codex's reserved
136		// <CODEX_HOME>/agents tree would be rejected by its agent-role scanner
137		// at every startup (entireio/cli#842). A leftover config.toml written
138		// by an older entire version must be removed manually.
139		return count, nil
140	}
