214	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
215	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
216		repoRoot, err := paths.WorktreeRoot(ctx)
217		if err != nil {
218			repoRoot = "."
219		}
220	
221		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
222		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
223		if err != nil {
224			return false
225		}
226	
227		var hooksFile HooksFile
228		if err := json.Unmarshal(data, &hooksFile); err != nil {
229			return false
230		}
231	
232		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
233			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
234			hasEntireHook(hooksFile.Hooks.Stop) &&
235			hasEntireHook(hooksFile.Hooks.PostToolUse)
236	}
