238	// --- Helpers ---
239	
240	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
241		if data, ok := rawHooks[hookType]; ok {
242			if err := json.Unmarshal(data, target); err != nil {
243				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
244			}
245		}
246		return nil
247	}
248	
249	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
250		if len(groups) == 0 {
251			delete(rawHooks, hookType)
252			return
253		}
254		data, err := jsonutil.MarshalWithNoHTMLEscape(groups)
255		if err != nil {
256			return
257		}
258		rawHooks[hookType] = data
259	}
260	
261	func hookCommandExists(groups []MatcherGroup, command string) bool {
262		for _, group := range groups {
263			for _, hook := range group.Hooks {
264				if hook.Command == command {
265					return true
266				}
267			}
268		}
269		return false
270	}
271	
272	// syncHookCommand ensures groups contains exactly the given Entire hook command
273	// and no other Entire-owned entry, reporting whether the config changed.
274	//
275	// Stale entries are dropped even when command is already present. Checking
276	// presence first (as this did before) left a hook written by an older version
277	// sitting next to the current one, so both fired — for the removed local-dev mode
278	// that meant a script inside the working tree kept running on every agent turn.
279	func syncHookCommand(groups []MatcherGroup, command string) ([]MatcherGroup, bool) {
280		groups, dropped := dropStaleEntireHooks(groups, command)
281		if hookCommandExists(groups, command) {
282			return groups, dropped
283		}
284		return addHook(groups, command), true
285	}
286	
287	// dropStaleEntireHooks removes Entire-owned hooks whose command is not one of
288	// want, per matcher group, pruning groups left with no hooks. See
289	// agent.DropStaleManagedHooks for why this runs on every install.
290	func dropStaleEntireHooks(groups []MatcherGroup, want ...string) ([]MatcherGroup, bool) {
291		result := make([]MatcherGroup, 0, len(groups))
292		dropped := false
293		for _, group := range groups {
294			kept, d := agent.DropStaleManagedHooks(group.Hooks, hookEntryCommand, want)
295			if d {
296				dropped = true
297			}
298			if len(kept) > 0 {
299				group.Hooks = kept
300				result = append(result, group)
301			}
302		}
303		if !dropped {
304			return groups, false
305		}
306		return result, true
307	}
308	
309	// hookEntryCommand reads the command off a hook entry for the shared helpers.
310	func hookEntryCommand(e HookEntry) string { return e.Command }
311	
312	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
313		entry := HookEntry{
314			Type:    "command",
315			Command: command,
316			Timeout: 30,
317		}
318	
319		// Add to an existing group with null matcher, or create a new one
320		for i, group := range groups {
321			if group.Matcher == nil {
322				groups[i].Hooks = append(groups[i].Hooks, entry)
323				return groups
324			}
325		}
326		return append(groups, MatcherGroup{
327			Matcher: nil,
328			Hooks:   []HookEntry{entry},
329		})
330	}
331	
332	func isEntireHook(command string) bool {
333		return agent.IsManagedHookCommand(command)
334	}
335	
336	func hasEntireHook(groups []MatcherGroup) bool {
337		for _, group := range groups {
338			for _, hook := range group.Hooks {
339				if isEntireHook(hook.Command) {
340					return true
341				}
342			}
343		}
344		return false
345	}
346	
347	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
348		result := make([]MatcherGroup, 0, len(groups))
349		for _, group := range groups {
350			filtered := make([]HookEntry, 0, len(group.Hooks))
351			for _, hook := range group.Hooks {
352				if !isEntireHook(hook.Command) {
353					filtered = append(filtered, hook)
354				}
355			}
356			if len(filtered) > 0 {
357				group.Hooks = filtered
358				result = append(result, group)
359			}
360		}
361		return result
362	}
