30	// managedHook describes one hooks.json event Entire owns. Keeping the event
31	// key, verb, timeout and production wrapper together means adding or removing
32	// an event is a single table edit rather than parallel edits in InstallHooks,
33	// UninstallHooks and AreHooksInstalled.
34	type managedHook struct {
35		event   string // hooks.json key
36		verb    string // `entire hooks codex <verb>`
37		timeout int
38		wrap    func(cmd string, windows bool) string
39	
40		// core marks the events whose absence means Codex was never enabled in this
41		// repo, as opposed to enabled against an older release that installed fewer
42		// events. Only these gate AreHooksInstalled — see the comment there.
43		core bool
44	}
45	
46	// managedHooks is the full set of Codex events Entire installs.
47	var managedHooks = []managedHook{
48		{event: "SessionStart", verb: HookNameSessionStart, timeout: defaultHookTimeoutSec, core: true, wrap: func(cmd string, windows bool) string {
49			return agent.WrapProductionJSONWarningHookCommandForOS(cmd, agent.WarningFormatSingleLine, windows)
50		}},
51		// SessionEnd is the one event Codex clamps: it caps handlers at
52		// SESSION_END_MAX_TIMEOUT_SEC and warns at every startup when a config asks
53		// for more, so it is installed at exactly the ceiling. See SessionEndTimeoutSec.
54		//
55		// Not core: it postdates the four events below, so requiring it would
56		// un-enable Codex for everyone who enabled it before this release.
57		{event: "SessionEnd", verb: HookNameSessionEnd, timeout: SessionEndTimeoutSec, wrap: agent.WrapProductionSilentHookCommandForOS},
58		{event: "UserPromptSubmit", verb: HookNameUserPromptSubmit, timeout: defaultHookTimeoutSec, core: true, wrap: agent.WrapProductionSilentHookCommandForOS},
59		{event: "Stop", verb: HookNameStop, timeout: defaultHookTimeoutSec, core: true, wrap: agent.WrapProductionSilentHookCommandForOS},
60		{event: "PostToolUse", verb: HookNamePostToolUse, timeout: defaultHookTimeoutSec, core: true, wrap: agent.WrapProductionSilentHookCommandForOS},
61	}
