64	func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
65		repoRoot, err := paths.WorktreeRoot(ctx)
66		if err != nil {
67			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
68			if err != nil {
69				return 0, fmt.Errorf("failed to get current directory: %w", err)
70			}
71		}
72	
